mapper.insert:

INSERT INTO news_push_plan_item (plan_id, item_id)
SELECT #{planId}, receipt.item_id
FROM news_push_plan_delivery receipt
WHERE receipt.plan_id = #{planId}
  AND (

        (receipt.app_id = #{target.appId} AND receipt.open_id = #{target.openId})

  )
GROUP BY receipt.item_id
HAVING COUNT(*) = #{targetCount}
ON DUPLICATE KEY UPDATE item_id = VALUES(item_id)

mapper.delete:
DELETE receipt FROM news_push_plan_delivery receipt
INNER JOIN news_push_plan_item completed ON completed.plan_id = receipt.plan_id AND completed.item_id = receipt.item_id
WHERE receipt.plan_id = #{planId}
